/** The booking in progress: the screening and the identifiers of the selected seats (a couch has two). */
export interface Booking {
  screeningId: number;
  seats: string[];
}

const STORAGE_KEY = 'cinescope.booking';

/** Holds the booking in progress and keeps it in `sessionStorage`, so it survives a reload. */
@Injectable({ providedIn: 'root' })
export class BookingStore {
  private readonly current = signal<Booking | null>(readStoredBooking());

  readonly booking = this.current.asReadonly();

  /** Starts an empty booking for the screening, unless the booking in progress already belongs to it. */
  openFor(screeningId: number): void {
    if (this.current()?.screeningId !== screeningId) {
      this.save({ screeningId, seats: [] });
    }
  }

  setSeats(seats: string[]): void {
    const booking = this.current();
    if (booking !== null) {
      this.save({ ...booking, seats });
    }
  }

  clear(): void {
    this.current.set(null);
    sessionStorage.removeItem(STORAGE_KEY);
  }

  private save(booking: Booking): void {
    this.current.set(booking);
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }
}

